begin;
set local search_path=public,extensions;
select no_plan();
create temporary table push_fixture(alert uuid,subscription uuid);
insert into push_fixture(alert) values(gen_random_uuid());
grant all on push_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.register_push_subscription('30000000-0000-4000-8000-000000000001','{"endpoint":"http://127.0.0.1/private","keys":{"p256dh":"invalid","auth":"invalid"}}',true)$$,'P0001','Invalid supported push subscription','Push endpoint cannot address private server resources');
select lives_ok($$select public.register_push_subscription('30000000-0000-4000-8000-000000000001',jsonb_build_object('endpoint','https://fcm.googleapis.com/test-fixture','keys',jsonb_build_object('p256dh',repeat('A',87),'auth',repeat('A',22))),true)$$,'Recipient can opt their registered device into push');
update push_fixture set subscription=(select id from public.push_subscription where user_id=wise_auth.uid() and device_id='30000000-0000-4000-8000-000000000001');
select ok(not has_function_privilege('authenticated','public.claim_push_deliveries()','execute'),'Browser cannot claim or read other recipients delivery jobs');
reset role;
insert into public.notification(id,cooperative_id,kind,payload) select alert,'10000000-0000-4000-8000-000000000001','task','{}' from push_fixture;
select is((select count(*)::integer from public.push_delivery where notification_id=(select alert from push_fixture) and subscription_id=(select subscription from push_fixture)),1,'New cooperative alert queues opted-in registered devices');
select is((select count(*)::integer from public.claim_push_deliveries() job where job->>'notification_id'=(select alert::text from push_fixture)),1,'Service worker claim returns queued delivery once');
select is((select count(*)::integer from public.claim_push_deliveries() job where job->>'notification_id'=(select alert::text from push_fixture)),0,'Lease prevents concurrent duplicate delivery');
select is((select attempts from public.push_delivery where notification_id=(select alert from push_fixture) and subscription_id=(select subscription from push_fixture)),1,'Delivery retry attempts are recorded');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000008","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.push_subscription where id=(select subscription from push_fixture)),0,'Other cooperative cannot read endpoint or encryption keys');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.register_push_subscription('30000000-0000-4000-8000-000000000001','{}',false)$$,'Recipient can withdraw device consent');
reset role;
update public.push_delivery set next_attempt_at=now() where notification_id=(select alert from push_fixture);
select is((select count(*)::integer from public.claim_push_deliveries() job where job->>'notification_id'=(select alert::text from push_fixture)),0,'Withdrawn device consent prevents retry delivery');
select * from finish();
rollback;
